import argparse
from fractions import Fraction
import os
import struct
import sys
import av

# Protocol Flags from Java Code
PACKET_FLAG_CONFIG = 1 << 63
PACKET_FLAG_KEY_FRAME = 1 << 62
PTS_MASK = (1 << 62) - 1
HEADER_SIZE = 12


def parse_custom_stream(file_path):
    """Reads the custom binary format generated by QuestScrcpyMini."""
    with open(file_path, "rb") as f:
        while True:
            header = f.read(HEADER_SIZE)
            if len(header) < HEADER_SIZE:
                break

            pts_and_flags, payload_len = struct.unpack(">QI", header)

            is_config = bool(pts_and_flags & PACKET_FLAG_CONFIG)
            is_keyframe = bool(pts_and_flags & PACKET_FLAG_KEY_FRAME)
            pts_ms = pts_and_flags & PTS_MASK

            payload = f.read(payload_len)
            if len(payload) < payload_len:
                print(
                    "Warning: Truncated frame payload encountered.",
                    file=sys.stderr,
                )
                break

            yield pts_ms, is_config, is_keyframe, payload


def convert_to_mp4_and_export_timestamps(
    input_file, output_file, fps=60, constant_fps=False, start_time_ns=None, offset_ms=0
):
    """Remuxes H.264 video to MP4 and exports frame timestamps to a .time binary file in nanoseconds (uint64)."""
    # Derive .time output path (e.g., "video.mp4" -> "video.time")
    base_path, _ = os.path.splitext(output_file)
    time_file_path = f"{base_path}.time"

    # Open MP4 container
    output = av.open(output_file, mode="w")
    stream = output.add_stream("h264", rate=fps)
    stream.time_base = Fraction(1, 1000)

    codec = av.CodecContext.create("h264", "r")

    first_pts = None
    last_dts = -1
    frame_index = 0
    packet_count = 0
    ts_count = 0

    print(f"Processing '{input_file}' -> '{output_file}'...")
    print(f"Exporting timestamps to '{time_file_path}'...")

    with open(time_file_path, "wb") as time_file:
        for pts_ms, is_config, is_keyframe, payload in parse_custom_stream(
            input_file
        ):
            packets = codec.parse(payload)

            # Codec extradata (SPS/PPS config headers)
            if is_config:
                if codec.extradata and not stream.codec_context.extradata:
                    stream.codec_context.extradata = codec.extradata
                continue

            # Capture initial PTS for relative video offset
            if first_pts is None and pts_ms > 0:
                first_pts = pts_ms

            for packet in packets:
                packet.stream = stream

                # --- 1. Calculate Video PTS/DTS for MP4 container ---
                if not constant_fps and first_pts is not None:
                    calculated_pts = max(0, pts_ms - first_pts)
                else:
                    calculated_pts = int(frame_index * (1000 / fps))

                dts = calculated_pts
                if dts <= last_dts:
                    dts = last_dts + 1

                packet.time_base = Fraction(1, 1000)
                packet.pts = calculated_pts
                packet.dts = dts

                last_dts = dts
                frame_index += 1

                output.mux(packet)
                packet_count += 1

                # --- 2. Calculate & Save Timestamp in Nanoseconds (uint64) ---
                if start_time_ns is not None:
                    # Remap relative to provided start_time_ns
                    delta_ms = max(0, pts_ms - (first_pts or pts_ms))
                    frame_ts_ns = start_time_ns + (delta_ms * 1_000_000)
                else:
                    # Store raw Quest timestamp in nanoseconds
                    frame_ts_ns = pts_ms * 1_000_000
                frame_ts_ns += offset_ms * 1_000_000

                # Write as Unsigned 64-bit Integer (little-endian: <Q)
                time_file.write(struct.pack("<Q", int(frame_ts_ns)))
                ts_count += 1

        # Flush remaining parser packets
        for packet in codec.parse():
            packet.stream = stream

            if not constant_fps:
                calculated_pts = last_dts + 1
            else:
                calculated_pts = int(frame_index * (1000 / fps))

            dts = max(calculated_pts, last_dts + 1)

            packet.time_base = Fraction(1, 1000)
            packet.pts = calculated_pts
            packet.dts = dts

            last_dts = dts
            frame_index += 1

            output.mux(packet)
            packet_count += 1

            # Save timestamp for flushed packets
            if first_pts is not None:
                if start_time_ns is not None:
                    frame_ts_ns = start_time_ns + (calculated_pts * 1_000_000)
                else:
                    frame_ts_ns = (first_pts + calculated_pts) * 1_000_000
                frame_ts_ns += offset_ms * 1_000_000
                time_file.write(struct.pack("<Q", int(frame_ts_ns)))
                ts_count += 1

    output.close()
    print(
        f"Done! Successfully remuxed {packet_count} frames into '{output_file}'."
    )
    print(f"Saved {ts_count} frame timestamps to '{time_file_path}'.")


if __name__ == "__main__":
    import json
    from adbutils import adb

    parser = argparse.ArgumentParser(
        description="Convert QuestScrcpyMini recordings to MP4 and export binary timestamps."
    )
    parser.add_argument(
        "-i", "--input", help="Path to custom recording file (e.g., mirror_hq.h264)", default=None
    )
    parser.add_argument(
        "-o", "--output", help="Output MP4 file path", default="export/Neon Scene Camera v1 ps1.mp4"
    )
    parser.add_argument(
        "-d", "--di", help="Adb device index", type=int, default=0
    )
    parser.add_argument(
        "--fps", type=int, default=60, help="Target framerate hint (default: 60)"
    )
    parser.add_argument(
        "--cfr",
        action="store_true",
        help="Force constant framerate video timing based on --fps",
    )
    parser.add_argument(
        "--start-time",
        type=int,
        default=None,
        help="Optional start timestamp in ms. First frame will be remapped to this value.",
    )

    args = parser.parse_args()

    info = None
    with open("data/info.json", "r") as f:
        info = json.load(f)

    dinput = args.input
    if dinput is None:
        dinput = "export/mirror_hq.h264"
        device = adb.device_list()[args.di]
        device.sync.pull("/sdcard/mirror_hq.h264", dinput)

    if not os.path.isfile(dinput):
        print(f"Error: Input file '{args.input}' not found.", file=sys.stderr)
        sys.exit(1)

    convert_to_mp4_and_export_timestamps(
        dinput,
        args.output,
        fps=args.fps,
        constant_fps=args.cfr,
        start_time_ns=args.start_time * 1_000_000 if args.start_time is not None else None,
        offset_ms = info["offset_start_ms"]
    )